<?php
require_once __DIR__.'/../includes/bootstrap.php';require_role('programme_officer');$user=current_user();$flashes=render_flashes();$currentPage='cohort_view';$pageTitle='Cohort Details';require_once __DIR__.'/_helpers.php';$conn=Database::getConnection();$officerId=(int)($user['id']??$user['user_id']??0);$cohortId=(int)($_GET['id']??0);if($officerId<=0||$cohortId<=0){http_response_code(400);exit('Invalid request.');}$scope=po_scope($conn,'p','c');$sql="SELECT c.*,p.name programme_name,p.type programme_type FROM cohorts c INNER JOIN programmes p ON p.id=c.programme_id WHERE c.id=? AND {$scope['condition']} LIMIT 1";$stmt=$conn->prepare($sql);$stmt->bind_param('ii',$cohortId,$officerId);$stmt->execute();$cohort=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$cohort){http_response_code(403);exit('Cohort not found or access denied.');}$participants=[];$sql="SELECT u.id,u.first_name,u.last_name,u.email,cp.status,cp.selected_at,cp.onboarded_at,cp.completed_at FROM cohort_participants cp INNER JOIN users u ON u.id=cp.user_id INNER JOIN cohorts c ON c.id=cp.cohort_id INNER JOIN programmes p ON p.id=c.programme_id WHERE cp.cohort_id=? AND {$scope['condition']} ORDER BY u.first_name,u.last_name";$stmt=$conn->prepare($sql);$stmt->bind_param('ii',$cohortId,$officerId);$stmt->execute();$r=$stmt->get_result();while($row=$r->fetch_assoc())$participants[]=$row;$stmt->close();$total=count(array_filter($participants,fn($p)=>($p['status']??'')!=='withdrawn'));$completed=count(array_filter($participants,fn($p)=>($p['status']??'')==='completed'));$active=count(array_filter($participants,fn($p)=>($p['status']??'')==='active'));$rate=po_completion_rate($total,$completed);require __DIR__.'/_layout_start.php';?>
<div class="po-breadcrumb"><a href="<?= url('programme_officer/cohorts.php') ?>">Cohorts</a><i class="fas fa-chevron-right"></i><span><?= e($cohort['name']) ?></span></div>
<section class="po-detail-hero"><div><span class="po-detail-hero__eyebrow"><?= e($cohort['programme_name']) ?></span><h2><?= e($cohort['name']) ?></h2><div class="po-detail-hero__meta"><span class="po-status po-status--<?= e(po_status_class($cohort['status'])) ?>"><?= e(po_status_label($cohort['status'])) ?></span><span><i class="fas fa-calendar"></i> <?= e(po_date($cohort['start_date'])) ?> – <?= e(po_date($cohort['end_date'])) ?></span></div></div><a class="po-btn po-btn--secondary" href="<?= url('programme_officer/candidates.php?cohort_id='.$cohortId) ?>"><i class="fas fa-users"></i> View Candidates</a></section>
<section class="po-stats po-stats--4"><article class="po-stat"><span class="po-stat__icon po-stat__icon--blue"><i class="fas fa-users"></i></span><strong><?= number_format($total) ?></strong><span>Current Candidates</span></article><article class="po-stat"><span class="po-stat__icon po-stat__icon--cyan"><i class="fas fa-person-running"></i></span><strong><?= number_format($active) ?></strong><span>Active</span></article><article class="po-stat"><span class="po-stat__icon po-stat__icon--green"><i class="fas fa-circle-check"></i></span><strong><?= number_format($completed) ?></strong><span>Completed</span></article><article class="po-stat"><span class="po-stat__icon po-stat__icon--purple"><i class="fas fa-chart-line"></i></span><strong><?= $rate ?>%</strong><span>Completion</span></article></section>
<div class="po-card"><div class="po-card__header"><div><h3>Cohort Participants</h3><p>Candidate participation and current status.</p></div></div><?php if(!$participants):?><div class="po-empty"><div class="po-empty__icon"><i class="fas fa-users"></i></div><strong>No participants</strong><span>No candidates are attached to this cohort.</span></div><?php else:?><div class="po-table-wrap"><table class="po-table"><thead><tr><th>Candidate</th><th>Status</th><th>Selected</th><th>Onboarded</th><th>Completed</th><th></th></tr></thead><tbody><?php foreach($participants as $p):$fn=trim((string)($p['first_name']??''));$ln=trim((string)($p['last_name']??''));?><tr><td><div class="po-person"><div class="po-avatar"><?= e(po_initials($fn,$ln)) ?></div><div><strong><?= e(trim($fn.' '.$ln)?:'Candidate') ?></strong><span><?= e((string)$p['email']) ?></span></div></div></td><td><span class="po-status po-status--<?= e(po_status_class($p['status'])) ?>"><?= e(po_status_label($p['status'])) ?></span></td><td><?= e(po_date($p['selected_at'],'—')) ?></td><td><?= e(po_date($p['onboarded_at'],'—')) ?></td><td><?= e(po_date($p['completed_at'],'—')) ?></td><td class="po-table__action"><a class="po-icon-btn" href="<?= url('programme_officer/candidate_view.php?id='.(int)$p['id'].'&cohort_id='.$cohortId) ?>"><i class="fas fa-arrow-right"></i></a></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<?php require __DIR__.'/_layout_end.php';?>
